{
    public ProofOfIntentTraining(AppDbContext db, Dictionary<string, int> slugMap) : base(db, slugMap) { }

    public override IReadOnlyList<string> Capabilities =>
    [
        "CAP-O2C-SO-ACCEPTANCE",
    ];

    public override async Task SeedAsync()
    {
        await GetOrCreateModule(new TrainingModule
        {
            Title = "Proof of Intent",
            Slug = "proof-of-intent-overview",
            Summary = "How a customer's emailed purchase order becomes a reviewed draft order, and how the order proves who authorized it.",
            ContentType = TrainingContentType.Article,
            EstimatedMinutes = 7,
            IsPublished = true,
            SortOrder = 1,
            AppRoutes = """["/sales-orders"]""",
            Tags = """["proof-of-intent","sales-orders","communications"]""",
            ContentJson = """{"body":"## Proof of Intent\n\nWhen a customer emails you a purchase order, that email is the proof they asked for the work. Proof of Intent keeps that proof attached to the sales order it produced, so months later anyone can answer \"who authorized this, when, and with what document?\" without digging through a mailbox.\n\n### How a message becomes an order\n\nIncoming messages from senders you have allowed are stored exactly as they arrived — the message and every attachment — and each stored document is given a **fingerprint** (a SHA-256 hash). The fingerprint proves the document has not changed since it was received. Forge reads the message and proposes a draft order from it: customer, PO number, items, quantities and prices.\n\nNothing becomes an order on its own. A person always reviews the proposal on the **Review Message** screen and approves it. There is no setting that skips this step.\n\n### The review screen\n\nThe screen has two halves side by side. On the left, **What arrived**: the message text, the **Stored documents** with their fingerprints and sizes, any **Prior agreements on file** for that customer, and the rest of the conversation. On the right, **Proposed order**: the pre-filled draft.\n\nEverything on the right is editable, and what you approve is what is on the screen — not what was originally read out of the message. If the extraction got a quantity wrong, correct it before approving. Reading the document while you check the numbers is the whole point of the layout, which is why the evidence is beside the form rather than on another tab.\n\n### Who sent it matters\n\nThe chip at the top says how firmly the sender was identified:\n\n- **Sender confirmed** — the exact address belongs to a known contact at the customer.\n- **Domain only** — the address is at the customer's company domain, but it is not a known contact.\n- **Unknown sender** — no match.\n\n**Only a confirmed sender can be approved into an order.** A domain match proves someone at the company wrote in, not who — and anyone at that domain can send mail. When the sender is not confirmed, the approve button is disabled and the screen says why. The fix is to confirm the contact with the customer and add them, not to approve anyway.\n\n### Choosing the authorizing document\n\nOn the draft, **Authorizing document** asks which of the stored documents *is* the customer's authorization — usually their purchase order PDF, not the email body. **Backed by** lets you point at a standing agreement already on file (a master agreement, signed terms, an accepted quote) that the PO relies on. If no prior agreement is on file, the screen warns you: a purchase order on its own may not be enough authorization for your business — check before approving.\n\n### Approve into draft\n\nFill in or correct the customer, PO number, need-by date, items, tax rate and note, then click **Approve into draft**. Forge creates a draft sales order and records an **attestation** — a statement that this customer, through this document, authorized this order. From there the order goes through the normal sales-order flow.\n\n### The Authorized by line\n\nOpen the sales order and look at the top of its overview. Orders that came from a reviewed message show one line:\n\n*Authorized by PO-8832.pdf — received 08/15/2026 09:12 AM from bob@bobsparts.com — sha256:ab3f91…*\n\nEach piece links somewhere: the document name opens the stored document, the sender address opens the original message, and if prior agreements back the order, a **prior agreement(s) behind this** toggle expands the chain. Orders that were keyed in by hand or converted from a quote show nothing here — the line only appears when there is real proof behind the order, so that when you do see it, it means something.\n\n### Copying the fingerprint\n\nThe fingerprint on screen is shortened so it fits. Clicking it copies the **full 64-character** value to your clipboard. If anyone ever needs to verify that a document is the one the customer sent, they run the fingerprint against the stored file; a shortened value cannot do that, so always use the copy button rather than retyping what you see.","sections":[]}"""
        });

        await GetOrCreateModule(new TrainingModule
        {
            Title = "Proof of Intent — Reference",
            Slug = "proof-of-intent-quick-reference",
            Summary = "Sender confidence levels, the review screen fields, and each part of the Authorized by line.",
            ContentType = TrainingContentType.QuickRef,
            EstimatedMinutes = 3,
            IsPublished = true,
            SortOrder = 2,
            AppRoutes = """["/sales-orders"]""",
            Tags = """["proof-of-intent","quick-reference"]""",
            ContentJson = """{"title":"Proof of Intent Reference","groups":[{"heading":"Sender confidence (chip on Review Message)","items":[{"label":"Sender confirmed","value":"Exact address belongs to a known contact at the customer. The only level that can be approved into an order."},{"label":"Domain only","value":"Address is at the customer's company domain but is not a known contact. Approve is disabled. Confirm the contact with the customer first."},{"label":"Unknown sender","value":"No match. Approve is disabled."}]},{"heading":"What arrived (left panel)","items":[{"label":"Stored documents","value":"The message and each attachment, stored unchanged, each with its size and fingerprint (SHA-256). Hover the short fingerprint to see the full value."},{"label":"Prior agreements on file","value":"Standing agreements already recorded for this customer. A warning appears when there are none."},{"label":"Rest of this conversation","value":"Other messages in the same thread, by date and subject."}]},{"heading":"Proposed order (right panel)","items":[{"label":"Customer (required)","value":"The account the order is for. Pre-filled from the sender match; change it if wrong."},{"label":"Authorizing document (required)","value":"Which stored document IS the customer's authorization. Usually their purchase order, not the email body."},{"label":"Backed by","value":"Optional. A prior agreement the authorizing document relies on. Becomes the chain shown on the order."},{"label":"Customer PO","value":"The customer's PO number, up to 50 characters."},{"label":"Need by","value":"Requested delivery date."},{"label":"Items","value":"Description, quantity and unit price per line. Fully editable; what you approve is what is on screen."},{"label":"Tax rate / Note","value":"Applied to the draft order."},{"label":"Approve into draft","value":"Creates the draft sales order and records the attestation. Disabled unless the sender is confirmed and the form is complete."}]},{"heading":"Authorized by line (sales order overview)","items":[{"label":"Document name","value":"Opens the stored authorizing document."},{"label":"received (date and time)","value":"When the message arrived, not when it was approved."},{"label":"from (address)","value":"Opens the original message on the Review Message screen."},{"label":"sha256: (fingerprint)","value":"Click to copy the full 64-character fingerprint. The display is shortened; the copy never is."},{"label":"prior agreement(s) behind this","value":"Expands the chain of earlier statements the authorization relies on, each with its own date and fingerprint."},{"label":"Line not shown","value":"The order has no attestation — it was keyed in or converted from a quote. This is normal for most orders."}]}]}"""
        });

        await GetOrCreateModule(new TrainingModule
        {
            Title = "Proof of Intent — Knowledge Check",
            Slug = "proof-of-intent-quiz",
            Summary = "Five questions on sender confidence, correcting the draft, the authorizing document, and the fingerprint.",
            ContentType = TrainingContentType.Quiz,
            EstimatedMinutes = 3,
            IsPublished = true,
            SortOrder = 3,
            AppRoutes = """["/sales-orders"]""",
            Tags = """["proof-of-intent","quiz"]""",
            ContentJson = """{"passingScore": 80, "shuffleQuestions": false, "shuffleOptions": true, "showExplanationsAfterSubmit": true, "questions": [{"id": "q1", "text": "A purchase order arrives from an address at the customer's domain, but the chip reads Domain only. What can you do?", "options": [{"id": "q1a", "text": "Approve it — the domain proves it came from the customer", "isCorrect": false}, {"id": "q1b", "text": "Nothing on this screen; confirm the contact with the customer and add them first", "isCorrect": true}, {"id": "q1c", "text": "Change the customer field to match and approve", "isCorrect": false}, {"id": "q1d", "text": "Edit the confidence chip to Sender confirmed", "isCorrect": false}], "explanation": "Only a confirmed sender can authorize an order. A domain match proves someone at the company wrote in, not who. The approve button stays disabled until the sender is a known contact."}, {"id": "q2", "text": "The proposal read a quantity of 10 but the PO says 100. What do you do?", "options": [{"id": "q2a", "text": "Approve it and fix the quantity on the sales order later", "isCorrect": false}, {"id": "q2b", "text": "Correct the quantity on the draft before approving — what is on screen is what is saved", "isCorrect": true}, {"id": "q2c", "text": "Reject the message and ask the customer to resend", "isCorrect": false}, {"id": "q2d", "text": "Add a note saying the quantity is wrong", "isCorrect": false}], "explanation": "The draft is fully editable and the approval saves the reviewer's values, not the extraction's. That is why the document sits beside the form."}, {"id": "q3", "text": "Which stored document should normally be chosen as the Authorizing document?", "options": [{"id": "q3a", "text": "The email message body", "isCorrect": false}, {"id": "q3b", "text": "The customer's purchase order attachment", "isCorrect": true}, {"id": "q3c", "text": "Whichever is largest", "isCorrect": false}, {"id": "q3d", "text": "The oldest message in the thread", "isCorrect": false}], "explanation": "The authorizing document is the one that IS the customer's authorization — usually their PO. The email that carried it is stored too, but the PO is what they signed off."}, {"id": "q4", "text": "Someone needs to verify a document is the one the customer sent. How do you give them the fingerprint?", "options": [{"id": "q4a", "text": "Read the short sha256 value shown on the order to them", "isCorrect": false}, {"id": "q4b", "text": "Click the fingerprint on the Authorized by line; it copies the full 64-character value", "isCorrect": true}, {"id": "q4c", "text": "Take a screenshot of the order", "isCorrect": false}, {"id": "q4d", "text": "Forward them the email", "isCorrect": false}], "explanation": "The on-screen value is shortened to fit. Verification needs all 64 characters, which is exactly what the copy button places on the clipboard."}, {"id": "q5", "text": "You open a sales order and there is no Authorized by line at all. What does that mean?", "options": [{"id": "q5a", "text": "The proof was deleted", "isCorrect": false}, {"id": "q5b", "text": "The order is on hold until someone approves it", "isCorrect": false}, {"id": "q5c", "text": "The order was keyed in or converted from a quote and has no attestation — that is normal", "isCorrect": true}, {"id": "q5d", "text": "The feature is turned off", "isCorrect": false}], "explanation": "The line appears only when an order carries a real attestation. Most orders do not, and showing an empty state on all of them would teach people to ignore the line where it matters."}]}"""
        });
    }
}
